#!/usr/bin/env python3
"""Generate README, PRD, ARCHITECTURE and AGENTS from reviewed Markdown records."""

from __future__ import annotations

import argparse
import re
import sys
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
WORKSPACE = ROOT / ".agents"
HEADER = "<!-- Generated by .github/scripts/generate_documents.py; edit source records instead. -->"

# (source directory relative to .agents, required status, generated filename, title)
PROJECTIONS = (
    ("notes", "published", "README.md", "Repository template"),
    ("requests", "approved", "PRD.md", "Product requirements"),
    ("decisions", "accepted", "ARCHITECTURE.md", "Architecture"),
    ("rules", "active", "AGENTS.md", "Agent and contributor rules"),
)


def parse_source(file: Path, allow_plain_notes: bool) -> tuple[str | None, str]:
    """Read a source and its status; unmarked ordinary notes remain unpublished."""
    contents = file.read_text(encoding="utf-8").replace("\r\n", "\n")
    front = re.match(r"\A---\n(.*?)\n---\n", contents, flags=re.DOTALL)
    if not front:
        if allow_plain_notes:
            return None, ""
        raise ValueError(f"Missing YAML-style front matter: {file.relative_to(ROOT)}")
    status = re.search(r"(?m)^status:\s*([a-z_-]+)\s*$", front.group(1))
    if status is None:
        raise ValueError(f"Missing status field: {file.relative_to(ROOT)}")
    return status.group(1), contents[front.end():].strip()


def content_for(directory: str, required_status: str, heading: str) -> str:
    """Render a single projection from source records in stable filename order."""
    source = WORKSPACE / directory
    if not source.is_dir():
        raise ValueError(f"Missing canonical source directory: {source.relative_to(ROOT)}")
    parts = [f"# {heading}\n\n{HEADER}\n"]
    included = 0
    for file in sorted(source.glob("*.md")):
        status, body = parse_source(file, allow_plain_notes=directory == "notes")
        if status != required_status:
            continue
        if not body.startswith("# "):
            raise ValueError(f"Source must begin with a level-one heading: {file.relative_to(ROOT)}")
        # Convert source H1s to section headings in the generated document.
        body = re.sub(r"(?m)^(#{1,5})(?= )", lambda match: "#" + match.group(1), body)
        parts.append(f"\n{body}\n\n_Source: [{file.name}]({directory}/{file.name})_\n")
        included += 1
    if included == 0:
        raise ValueError(f"No {required_status} source records in {source.relative_to(ROOT)}")
    return "\n".join(parts).rstrip() + "\n"


def validate_layout() -> list[str]:
    """Validate real root directories, symlinks, submodule and sole test location."""
    errors: list[str] = []
    for directory in (".agents", ".github"):
        root_directory = ROOT / directory
        if not root_directory.is_dir() or root_directory.is_symlink():
            errors.append(f"{directory}/ must be an actual directory, not a symlink")
    for name, target in (
        ("README.md", ".agents/README.md"),
        ("CONTRIBUTING.md", ".agents/AGENTS.md"),
    ):
        link = ROOT / name
        if not link.is_symlink() or link.readlink().as_posix() != target:
            errors.append(f"{name} must be a Git symlink to {target}")

    for old in (
        "notes/GOAL.md", "notes/PRD.md", "notes/ARCHITECTURE.md", "notes/TODO.md",
        "notes/requests", "notes/decisions", "notes/rules",
    ):
        if (WORKSPACE / old).exists():
            errors.append(f"Obsolete workspace path: .agents/{old}")
    if not (WORKSPACE / "TODO.md").is_file():
        errors.append("Missing canonical task file: .agents/TODO.md")

    profiles = sorted((WORKSPACE / "agents").glob("*.md"))
    skills = sorted((WORKSPACE / "skills").glob("*/SKILL.md"))
    if not profiles:
        errors.append("No agent role profiles found in .agents/agents/")
    if not skills:
        errors.append("No skills found in .agents/skills/")
    for file in profiles + skills:
        contents = file.read_text(encoding="utf-8")
        if not re.match(r"\A---\nname: [a-z0-9-]+\ndescription: .+\n---\n", contents):
            errors.append(f"Missing name/description metadata: {file.relative_to(ROOT)}")

    tests = ROOT / ".github" / "tests"
    if not tests.is_dir() or not list(tests.glob("test_*.py")):
        errors.append("Missing central tests under .github/tests/")
    tracked = subprocess.run(
        ["git", "ls-files", "-z"], cwd=ROOT, text=True,
        capture_output=True, check=False,
    )
    if tracked.returncode != 0:
        errors.append("Cannot audit test ownership: " + tracked.stderr.strip())
    else:
        for path in filter(None, tracked.stdout.split("\0")):
            if path.startswith(".github/tests/"):
                continue
            segments = path.split("/")
            leaf = segments[-1]
            is_test_directory = any(
                p.lower() in {
                    "test", "tests", "__tests__", "spec", "specs", "fixtures",
                    "__fixtures__", "snapshots", "__snapshots__", "mocks", "__mocks__",
                }
                for p in segments[:-1]
            )
            is_test_filename = leaf.startswith(("test_", "test-")) or bool(
                re.search(r"(?i)(?:[._-]test|[._-]spec|[._-]e2e|[._-]cy)\.[^.]+$", leaf)
            )
            if is_test_directory or is_test_filename:
                errors.append(f"Repository tests must live in .github/tests/: {path}")

    submodule = subprocess.run(
        ["git", "ls-files", "--stage", "--", ".darkfactory"],
        cwd=ROOT, capture_output=True, text=True, check=False,
    )
    if submodule.returncode != 0 or not re.fullmatch(
        r"160000 [0-9a-f]{40} 0\t\.darkfactory\n", submodule.stdout
    ):
        errors.append(".darkfactory must be a pinned root Git submodule (mode 160000)")
    if not (ROOT / ".gitmodules").is_file():
        errors.append("Missing .gitmodules entry for .darkfactory")
    else:
        submodules_text = (ROOT / ".gitmodules").read_text(encoding="utf-8")
        if "path = .darkfactory" not in submodules_text or "https://github.com/marius-patrik/DarkFactory.git" not in submodules_text:
            errors.append(".gitmodules must declare the DarkFactory root submodule")

    version = ROOT / "VERSION"
    try:
        import json
        config = json.loads((ROOT / "repo.dfconfig").read_text(encoding="utf-8"))
        mode = config["repo"].get("versioning", {}).get("mode", "tags")
        if mode not in {"tags", "file"}:
            errors.append("Unsupported repo.versioning.mode: " + str(mode))
        elif mode == "tags" and version.exists():
            errors.append("Tag-only mode must not track VERSION; use file mode to opt in")
        elif mode == "file" and (
            not version.is_file() or not re.fullmatch(
                r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\n",
                version.read_text(encoding="utf-8") if version.is_file() else "",
            )
        ):
            errors.append("File mode requires a strict major.minor.patch VERSION with newline")
    except (OSError, ValueError, KeyError) as error:
        errors.append("Invalid versioning configuration: " + str(error))
    return errors


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--write", action="store_true", help="Regenerate committed documents")
    group.add_argument("--check", action="store_true", help="Check committed documents")
    args = parser.parse_args()
    errors = []
    for directory, status, target, title in PROJECTIONS:
        expected = content_for(directory, status, title)
        output = WORKSPACE / target
        if args.write:
            output.write_text(expected, encoding="utf-8")
            print(f"generated {output.relative_to(ROOT)}")
        elif not output.is_file() or output.read_text(encoding="utf-8") != expected:
            errors.append(f"Stale generated document: {output.relative_to(ROOT)}")
    errors.extend(validate_layout())
    for error in errors:
        print(f"error: {error}", file=sys.stderr)
    if args.check and not errors:
        print("Generated documents, native directories, submodule, tests and versioning are consistent.")
    return int(bool(errors))


if __name__ == "__main__":
    raise SystemExit(main())
